// ===== 固定パターン定義 =====
// パターンA：市松模様 + (3,3)
// #*#* / *#** / #*#* / ***# (可変 = #, white = *)
const TILE_PATTERNS = {
  pattern_a: [
    [false, true,  false, true],
    [true,  false, true,  true],
    [false, true,  false, true],
    [true,  true,  true,  false]
  ],
  // パターンB：Tap me 標準 0●1●●2●3 / 4●5● / ●6●●
  pattern_b: [
    [false, true,  false, true],
    [true,  false, true,  false],
    [false, true,  false, true],
    [true,  false, true,  true]
  ]
};

// 互換性のため WHITE_TILE を定義（読み込み時は pattern_a を使用）
const WHITE_TILE = TILE_PATTERNS.pattern_a;

// 各カウント(0〜7)に対して、正確にそのビット数を持つ6ビットマスクを全列挙（座標巡回方式用）
const MULTI_MASKS = Array.from({length: 8}, (_, k) => {
  const masks = [];
  for (let mask = 0; mask < 64; mask += 1) {
    let bits = mask, count = 0;
    while (bits) { count += bits & 1; bits >>>= 1; }
    if (count === k) masks.push(mask);
  }
  return masks;
});

// ===== LUT方式（固定パターン）用データ =====
function lowFreqKey(rCount, gCount, bCount) {
  return (rCount << 6) | (gCount << 3) | bCount;
}

// 起動時に bestAssignment（最小マスク）を計算してLUTを構築
const LOWFREQ_PATTERNS = (() => {
  const N = 6;
  const bestAssignment = new Array(8).fill(0);
  const assigned = new Array(8).fill(false);
  for (let mask = 0; mask < (1 << N); mask += 1) {
    let count = 0;
    for (let i = 0; i < N; i += 1) count += (mask >> i) & 1;
    if (!assigned[count]) { bestAssignment[count] = mask; assigned[count] = true; }
  }
  const patterns = new Array(512);
  for (let rCount = 0; rCount <= 7; rCount += 1) {
    for (let gCount = 0; gCount <= 7; gCount += 1) {
      for (let bCount = 0; bCount <= 7; bCount += 1) {
        patterns[lowFreqKey(rCount, gCount, bCount)] =
          [bestAssignment[rCount], bestAssignment[gCount], bestAssignment[bCount]];
      }
    }
  }
  return patterns;
})();

