function applyGammaToImageData(imageData) {
  const { width, height, data } = imageData;
  if (!state.gammaEnabled || state.gammaValue === 0) return new ImageData(new Uint8ClampedArray(data), width, height);
  const source = new Uint8ClampedArray(data);
  const exponent = Math.pow(2, -state.gammaValue / 5);
  for (let i = 0; i < source.length; i += 4) {
    source[i]     = Math.round(Math.pow(source[i]     / 255, exponent) * 255);
    source[i + 1] = Math.round(Math.pow(source[i + 1] / 255, exponent) * 255);
    source[i + 2] = Math.round(Math.pow(source[i + 2] / 255, exponent) * 255);
  }
  return new ImageData(source, width, height);
}

async function maybeYield(progressMessage, current, total, timerRef) {
  const now = performance.now();
  if (now - timerRef.last > 18) {
    const percent = total > 0 ? ((current / total) * 100).toFixed(1) : "0.0";
    setStatus(`${progressMessage} ${percent}%`);
    timerRef.last = now;
    await new Promise((resolve) => requestAnimationFrame(resolve));
  }
}

// 候補の事前計算テーブル（0.0〜7.0の各値に対して候補を提供）
const CANDIDATE_CACHE = (() => {
  const cache = {};
  for (let i = 0; i <= 70; i++) {
    const target = i / 10;
    const rounded = Math.round(target);
    const candidates = new Set([
      Math.max(0, Math.min(7, rounded - 1)),
      Math.max(0, Math.min(7, rounded)),
      Math.max(0, Math.min(7, rounded + 1)),
      Math.max(0, Math.min(7, Math.floor(target))),
      Math.max(0, Math.min(7, Math.ceil(target)))
    ]);
    cache[i] = Array.from(candidates).sort((a, b) => a - b);
  }
  return cache;
})();

function lowFreqCandidateCounts(target) {
  // キャッシュされた候補を返す（0.0-7.0の範囲）
  const cacheIndex = Math.round(Math.max(0, Math.min(7, target)) * 10);
  return CANDIDATE_CACHE[cacheIndex];
}

// ===== 画素値分布の計算と描画 =====
function computeHistogram(imageData) {
  const histogram = new Array(256).fill(0);
  const { data } = imageData;
  
  for (let i = 0; i < data.length; i += 4) {
    const r = data[i];
    const g = data[i + 1];
    const b = data[i + 2];
    // グレースケール値：0-255にマッピング
    const gray = Math.round((r + g + b) / 3);
    histogram[gray]++;
  }
  
  return histogram;
}

function drawHistogram(canvas, ctx, histogram) {
  const width = canvas.offsetWidth;
  const height = canvas.offsetHeight;
  
  // DPI補正
  canvas.width = width * 2;
  canvas.height = height * 2;
  ctx.scale(2, 2);
  
  // 背景
  ctx.fillStyle = "#ffffff";
  ctx.fillRect(0, 0, width, height);
  
  // バウンディングボックスの余裕設定
  const padding = {
    left: 40,
    right: 10,
    top: 10,
    bottom: 30
  };
  const graphWidth = width - padding.left - padding.right;
  const graphHeight = height - padding.top - padding.bottom;
  
  // 縦軸を正規化（最大値を100%とする）
  const maxCount = Math.max(...histogram);
  
  // グリッド線と目盛り
  ctx.strokeStyle = "rgba(21, 32, 56, 0.1)";
  ctx.fillStyle = "rgba(21, 32, 56, 0.4)";
  ctx.font = "10px sans-serif";
  ctx.textAlign = "right";
  ctx.textBaseline = "middle";
  
  // 縦軸の目盛り（25%, 50%, 75%, 100%）
  const yAxisLabels = [0, 25, 50, 75, 100];
  yAxisLabels.forEach(percent => {
    const y = padding.top + graphHeight * (100 - percent) / 100;
    ctx.beginPath();
    ctx.moveTo(padding.left, y);
    ctx.lineTo(width - padding.right, y);
    ctx.stroke();
    ctx.fillText(percent + "%", padding.left - 8, y);
  });
  
  // ヒストグラム描画
  const barWidth = graphWidth / 256;
  ctx.fillStyle = "#274a91";
  
  histogram.forEach((count, index) => {
    if (maxCount === 0) return;
    const normalizedHeight = (count / maxCount) * 0.95 * graphHeight;
    const x = padding.left + (index * barWidth);
    const y = padding.top + graphHeight - normalizedHeight;
    ctx.fillRect(x, y, Math.max(1, barWidth - 0.5), normalizedHeight);
  });
  
  // 枠線
  ctx.strokeStyle = "rgba(21, 32, 56, 0.2)";
  ctx.lineWidth = 1;
  ctx.strokeRect(padding.left, padding.top, graphWidth, graphHeight);
}

// ===== 本体 =====
async function processHighFreqCut(sourceImageData) {
  const { width, height, data: sourceData } = sourceImageData;
  
  // オリジナル画像のヒストグラムを計算
  state.histogramOriginal = computeHistogram(sourceImageData);
  
  // 前処理：ガンマ補正を先に適用
  let source = sourceData;
  if (state.gammaEnabled && state.gammaValue !== 0) {
    source = new Uint8ClampedArray(sourceData);
    const gamma = state.gammaValue;
    const exponent = Math.pow(2, -gamma / 5);
    
    for (let i = 0; i < source.length; i += 4) {
      const r = source[i] / 255;
      const g = source[i + 1] / 255;
      const b = source[i + 2] / 255;
      
      source[i] = Math.round(Math.pow(r, exponent) * 255);
      source[i + 1] = Math.round(Math.pow(g, exponent) * 255);
      source[i + 2] = Math.round(Math.pow(b, exponent) * 255);
    }
    
    // ガンマ補正後のヒストグラムを計算
    state.histogramGamma = computeHistogram(new ImageData(source, width, height));
  } else {
    state.histogramGamma = null;
  }
  
  const output = new Uint8ClampedArray(source.length);
  const totalBlocks = Math.ceil(width / 4) * Math.ceil(height / 4);
  let completedBlocks = 0;
  const timerRef = { last: performance.now() };
  const activeTile = TILE_PATTERNS[state.activeTilePattern];

  for (let by = 0; by < height; by += 4) {
    const blockHeight = Math.min(4, height - by);
    for (let bx = 0; bx < width; bx += 4) {
      const blockWidth = Math.min(4, width - bx);

      if (blockWidth < 4 || blockHeight < 4) {
        for (let y = 0; y < blockHeight; y += 1) {
          const globalY = by + y;
          for (let x = 0; x < blockWidth; x += 1) {
            const globalX = bx + x;
            const index = (globalY * width + globalX) * 4;
            let r = source[index] >= 128 ? 255 : 0;
            let g = source[index + 1] >= 128 ? 255 : 0;
            let b = source[index + 2] >= 128 ? 255 : 0;
            if (activeTile[globalY & 3][globalX & 3]) {
              r = state.tileColor.r;
              g = state.tileColor.g;
              b = state.tileColor.b;
            }
            output[index] = r;
            output[index + 1] = g;
            output[index + 2] = b;
            output[index + 3] = 255;
          }
        }
        completedBlocks += 1;
        await maybeYield("Processing...", completedBlocks, totalBlocks, timerRef);
        continue;
      }

      // 4x4ブロック内のRGB総和を求める（展開ループで効率化）
      let sourceSumR = 0;
      let sourceSumG = 0;
      let sourceSumB = 0;
      for (let y = 0; y < 4; y += 1) {
        const rowBase = (by + y) * width;
        for (let x = 0; x < 4; x += 1) {
          const index = (rowBase + bx + x) * 4;
          sourceSumR += source[index];
          sourceSumG += source[index + 1];
          sourceSumB += source[index + 2];
        }
      }

      // 白固定10画素を差し引いた上で、可変画素に割り当てたいRGB個数を推定する
      const targetR = Math.max(0, Math.min(6, (sourceSumR - (10 * 255)) / 255));
      const targetG = Math.max(0, Math.min(6, (sourceSumG - (10 * 255)) / 255));
      const targetB = Math.max(0, Math.min(6, (sourceSumB - (10 * 255)) / 255));
      const rCandidates = lowFreqCandidateCounts(targetR);
      const gCandidates = lowFreqCandidateCounts(targetG);
      const bCandidates = lowFreqCandidateCounts(targetB);

      let bestState = [0, 0, 0];
      let bestError = Number.POSITIVE_INFINITY;

      // 最も近い単一候補を優先的にサンプル
      const rPrimary = Math.round(targetR);
      const gPrimary = Math.round(targetG);
      const bPrimary = Math.round(targetB);
      
      // 高速パス：最初に最も確実な候補をテスト
      for (const rCount of [Math.max(0, Math.min(7, rPrimary))]) {
        for (const gCount of [Math.max(0, Math.min(7, gPrimary))]) {
          for (const bCount of [Math.max(0, Math.min(7, bPrimary))]) {
            const blockError = 
              Math.abs((10 + rCount) * 255 - sourceSumR) +
              Math.abs((10 + gCount) * 255 - sourceSumG) +
              Math.abs((10 + bCount) * 255 - sourceSumB);
            if (blockError < bestError) {
              bestError = blockError;
              bestState = [rCount, gCount, bCount];
            }
          }
        }
      }

      // 完全一致でなければ候補全体をチェック
      if (bestError > 0) {
        for (const rCount of rCandidates) {
          for (const gCount of gCandidates) {
            for (const bCount of bCandidates) {
              const blockError =
                Math.abs((10 + rCount) * 255 - sourceSumR) +
                Math.abs((10 + gCount) * 255 - sourceSumG) +
                Math.abs((10 + bCount) * 255 - sourceSumB);
              if (blockError < bestError) {
                bestError = blockError;
                bestState = [rCount, gCount, bCount];
              }
            }
          }
        }
      }

      // 選択された方式でマスクを決定
      let rMask, gMask, bMask;
      if (colorModeSelect.value === "lut") {
        const entry = LOWFREQ_PATTERNS[lowFreqKey(bestState[0], bestState[1], bestState[2])];
        rMask = entry[0]; gMask = entry[1]; bMask = entry[2];
      } else {
        // 座標巡回方式（計算をブロック境界外で1回実行）
        const bxi = bx >> 2;
        const byi = by >> 2;
        const blockIndex = bxi + byi * Math.ceil(width / 4);
        const rMaskArr = MULTI_MASKS[bestState[0]];
        const gMaskArr = MULTI_MASKS[bestState[1]];
        const bMaskArr = MULTI_MASKS[bestState[2]];
        rMask = rMaskArr[blockIndex % rMaskArr.length];
        gMask = gMaskArr[(blockIndex * 7) % gMaskArr.length];
        bMask = bMaskArr[(blockIndex * 13) % bMaskArr.length];
      }
      let variableIndex = 0;

      for (let y = 0; y < 4; y += 1) {
        for (let x = 0; x < 4; x += 1) {
          const index = ((by + y) * width + (bx + x)) * 4;
          let r, g, b;
          if (activeTile[y][x]) {
            r = state.tileColor.r;
            g = state.tileColor.g;
            b = state.tileColor.b;
          } else {
            r = (rMask >> variableIndex) & 1 ? 255 : 0;
            g = (gMask >> variableIndex) & 1 ? 255 : 0;
            b = (bMask >> variableIndex) & 1 ? 255 : 0;
            variableIndex += 1;
          }
          output[index] = r;
          output[index + 1] = g;
          output[index + 2] = b;
          output[index + 3] = 255;
        }
      }

      completedBlocks += 1;
      await maybeYield("Processing...", completedBlocks, totalBlocks, timerRef);
    }
  }

  // 出力画像のヒストグラムを計算
  state.histogramOutput = computeHistogram(new ImageData(output, width, height));

  return {
    imageData: new ImageData(output, width, height),
    summary: {
      fileName: state.file?.name ?? "image",
      mode: "highFreqCut",
      modeLabel: "",
      width,
      height
    }
  };
}

// ===== 市松模様処理 =====
function isCheckerboardVisiblePixel(x, y) {
  // processCheckerboard と A/B 合成モードで必ず同じ配置を使う。
  // 元の市松模様モード: (0,0), (1,1), ... を保持し、反対側を透明化する。
  return (x & 1) === (y & 1);
}

async function processCheckerboard(sourceImageData) {
  const { width, height, data: sourceData } = sourceImageData;

  state.histogramOriginal = computeHistogram(sourceImageData);

  // ガンマ補正
  let source = sourceData;
  if (state.gammaEnabled && state.gammaValue !== 0) {
    source = new Uint8ClampedArray(sourceData);
    const exponent = Math.pow(2, -state.gammaValue / 5);
    for (let i = 0; i < source.length; i += 4) {
      source[i]     = Math.round(Math.pow(source[i]     / 255, exponent) * 255);
      source[i + 1] = Math.round(Math.pow(source[i + 1] / 255, exponent) * 255);
      source[i + 2] = Math.round(Math.pow(source[i + 2] / 255, exponent) * 255);
    }
    state.histogramGamma = computeHistogram(new ImageData(source, width, height));
  } else {
    state.histogramGamma = null;
  }

  const output = new Uint8ClampedArray(source.length);
  const timerRef = { last: performance.now() };

  for (let y = 0; y < height; y += 1) {
    for (let x = 0; x < width; x += 1) {
      const idx = (y * width + x) * 4;
      if (!isCheckerboardVisiblePixel(x, y)) {
        // 市松模様の置換画素: RGBA 0,0,0,0（完全透明）
        output[idx]     = 0;
        output[idx + 1] = 0;
        output[idx + 2] = 0;
        output[idx + 3] = 0;
      } else {
        // 元の色をそのまま保持
        output[idx]     = source[idx];
        output[idx + 1] = source[idx + 1];
        output[idx + 2] = source[idx + 2];
        output[idx + 3] = 255;
      }
    }
    await maybeYield("Processing...", y + 1, height, timerRef);
  }

  state.histogramOutput = computeHistogram(new ImageData(output, width, height));

  return {
    imageData: new ImageData(output, width, height),
    summary: {
      fileName: state.file?.name ?? "image",
      mode: "checkerboard",
      modeLabel: "",
      width,
      height
    }
  };
}

// ===== パレットPNGエンコーダー（市松模様・Twitter互換） =====

// CRC32テーブル
const CRC32_TABLE = (() => {
  const t = new Uint32Array(256);
  for (let i = 0; i < 256; i++) {
    let c = i;
    for (let j = 0; j < 8; j++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
    t[i] = c;
  }
  return t;
})();

function crc32(data) {
  let crc = 0xFFFFFFFF;
  for (let i = 0; i < data.length; i++) crc = CRC32_TABLE[(crc ^ data[i]) & 0xFF] ^ (crc >>> 8);
  return (crc ^ 0xFFFFFFFF) >>> 0;
}

function pngChunk(type, data) {
  const typeBytes = new TextEncoder().encode(type);
  const chunk = new Uint8Array(4 + 4 + data.length + 4);
  const view = new DataView(chunk.buffer);
  view.setUint32(0, data.length);
  chunk.set(typeBytes, 4);
  chunk.set(data, 8);
  const crcInput = new Uint8Array(4 + data.length);
  crcInput.set(typeBytes);
  crcInput.set(data, 4);
  view.setUint32(8 + data.length, crc32(crcInput));
  return chunk;
}

// メディアンカット色量子化（最大maxColors色）
function quantizeColors(rgbaData, maxColors) {
  // 非透明ピクセルをサンプリング（最大60000点）
  const totalPixels = rgbaData.length / 4;
  const step = Math.max(1, Math.floor(totalPixels / 60000));
  const samples = [];
  for (let i = 0; i < totalPixels; i += step) {
    if (rgbaData[i * 4 + 3] !== 0) {
      samples.push(rgbaData[i * 4], rgbaData[i * 4 + 1], rgbaData[i * 4 + 2]);
    }
  }
  if (samples.length === 0) return [[128, 128, 128]];

  function cut(flat, depth, maxDepth) {
    if (depth >= maxDepth || flat.length <= 3) {
      let r = 0, g = 0, b = 0;
      for (let i = 0; i < flat.length; i += 3) { r += flat[i]; g += flat[i+1]; b += flat[i+2]; }
      const n = flat.length / 3;
      return [[Math.round(r/n), Math.round(g/n), Math.round(b/n)]];
    }
    let minR=255,maxR=0,minG=255,maxG=0,minB=255,maxB=0;
    for (let i = 0; i < flat.length; i += 3) {
      if (flat[i]   < minR) minR=flat[i];   if (flat[i]   > maxR) maxR=flat[i];
      if (flat[i+1] < minG) minG=flat[i+1]; if (flat[i+1] > maxG) maxG=flat[i+1];
      if (flat[i+2] < minB) minB=flat[i+2]; if (flat[i+2] > maxB) maxB=flat[i+2];
    }
    const ch = (maxR-minR >= maxG-minG && maxR-minR >= maxB-minB) ? 0 : (maxG-minG >= maxB-minB ? 1 : 2);
    const list = [];
    for (let i = 0; i < flat.length; i += 3) list.push([flat[i], flat[i+1], flat[i+2]]);
    list.sort((a, b) => a[ch] - b[ch]);
    const mid = Math.floor(list.length / 2);
    return [...cut(list.slice(0, mid).flat(), depth+1, maxDepth),
            ...cut(list.slice(mid).flat(),    depth+1, maxDepth)];
  }

  const maxDepth = Math.ceil(Math.log2(maxColors));
  return cut(samples, 0, maxDepth).slice(0, maxColors);
}

// A/B 合成用: 複数画像から共通パレットを作る
function quantizeColorsFromImageDataList(imageDataList, maxColors) {
  const totalPixels = imageDataList.reduce((sum, imageData) => sum + imageData.data.length / 4, 0);
  const step = Math.max(1, Math.floor(totalPixels / 70000));
  const samples = [];
  for (const imageData of imageDataList) {
    const rgbaData = imageData.data;
    const pixels = rgbaData.length / 4;
    for (let i = 0; i < pixels; i += step) {
      const o = i * 4;
      if (rgbaData[o + 3] !== 0) samples.push(rgbaData[o], rgbaData[o + 1], rgbaData[o + 2]);
    }
  }
  if (samples.length === 0) return [[128, 128, 128]];

  function cut(flat, depth, maxDepth) {
    if (depth >= maxDepth || flat.length <= 3) {
      let r = 0, g = 0, b = 0;
      for (let i = 0; i < flat.length; i += 3) { r += flat[i]; g += flat[i+1]; b += flat[i+2]; }
      const n = flat.length / 3;
      return [[Math.round(r/n), Math.round(g/n), Math.round(b/n)]];
    }
    let minR=255,maxR=0,minG=255,maxG=0,minB=255,maxB=0;
    for (let i = 0; i < flat.length; i += 3) {
      if (flat[i]   < minR) minR=flat[i];   if (flat[i]   > maxR) maxR=flat[i];
      if (flat[i+1] < minG) minG=flat[i+1]; if (flat[i+1] > maxG) maxG=flat[i+1];
      if (flat[i+2] < minB) minB=flat[i+2]; if (flat[i+2] > maxB) maxB=flat[i+2];
    }
    const ch = (maxR-minR >= maxG-minG && maxR-minR >= maxB-minB) ? 0 : (maxG-minG >= maxB-minB ? 1 : 2);
    const list = [];
    for (let i = 0; i < flat.length; i += 3) list.push([flat[i], flat[i+1], flat[i+2]]);
    list.sort((a, b) => a[ch] - b[ch]);
    const mid = Math.floor(list.length / 2);
    return [...cut(list.slice(0, mid).flat(), depth+1, maxDepth),
            ...cut(list.slice(mid).flat(),    depth+1, maxDepth)];
  }

  const maxDepth = Math.ceil(Math.log2(maxColors));
  return cut(samples, 0, maxDepth).slice(0, maxColors);
}

function buildPaletteColors(quantized) {
  const paletteColors = new Array(256);
  for (let i = 0; i < quantized.length; i++) paletteColors[i] = quantized[i];
  for (let i = quantized.length; i < 255; i++) paletteColors[i] = [0, 0, 0];
  paletteColors[255] = [0, 0, 0];
  return paletteColors;
}

function mapImageDataToPaletteIndices(imageData, findNearest) {
  const { width, height, data } = imageData;
  const indices = new Uint8Array(width * height);
  for (let i = 0; i < width * height; i++) {
    const o = i * 4;
    indices[i] = data[o + 3] === 0 ? 255 : findNearest(data[o], data[o + 1], data[o + 2]);
  }
  return indices;
}

function imageDataFromPaletteIndices(width, height, indices, paletteColors) {
  const rgba = new Uint8ClampedArray(width * height * 4);
  for (let i = 0; i < indices.length; i++) {
    const o = i * 4;
    const index = indices[i];
    if (index === 255) {
      rgba[o] = 0; rgba[o + 1] = 0; rgba[o + 2] = 0; rgba[o + 3] = 0;
    } else {
      const c = paletteColors[index] || [0, 0, 0];
      rgba[o] = c[0]; rgba[o + 1] = c[1]; rgba[o + 2] = c[2]; rgba[o + 3] = 255;
    }
  }
  return new ImageData(rgba, width, height);
}

// 最近傍パレット色インデックスをキャッシュ付きで返す関数を構築
function buildNearestFinder(palette) {
  const cache = new Map();
  return function(r, g, b) {
    const key = (r >> 2) << 12 | (g >> 2) << 6 | (b >> 2);
    if (cache.has(key)) return cache.get(key);
    let best = 0, bestD = Infinity;
    for (let i = 0; i < palette.length; i++) {
      const dr = r - palette[i][0], dg = g - palette[i][1], db = b - palette[i][2];
      const d = dr*dr + dg*dg + db*db;
      if (d < bestD) { bestD = d; best = i; }
    }
    cache.set(key, best);
    return best;
  };
}

// パレットPNGバイナリを構築して Blob を返す
function encodePalettePNG(width, height, indices, paletteColors) {
  // PLTE: 256*3バイト（RGB）
  const plteData = new Uint8Array(256 * 3);
  for (let i = 0; i < 256; i++) {
    const c = paletteColors[i] || [0, 0, 0];
    plteData[i*3] = c[0]; plteData[i*3+1] = c[1]; plteData[i*3+2] = c[2];
  }

  // tRNS: index255=透明(0), それ以外=不透明(255)
  const trnsData = new Uint8Array(256).fill(255);
  trnsData[255] = 0;

  // 生データ: 各行の先頭にフィルタバイト0
  const rawData = new Uint8Array(height * (width + 1));
  for (let y = 0; y < height; y++) {
    rawData[y * (width + 1)] = 0;
    rawData.set(indices.subarray(y * width, (y + 1) * width), y * (width + 1) + 1);
  }

  // zlibで圧縮（pakoライブラリを使用）
  const compressed = pako.deflate(rawData);

  // IHDR
  const ihdrData = new Uint8Array(13);
  const ihdrView = new DataView(ihdrData.buffer);
  ihdrView.setUint32(0, width);
  ihdrView.setUint32(4, height);
  ihdrData[8] = 8; // bit depth
  ihdrData[9] = 3; // color type: indexed (palette)
  // [10],[11],[12] = 0 (compression, filter, interlace)

  const sig  = new Uint8Array([137, 80, 78, 71, 13, 10, 26, 10]);
  const ihdr = pngChunk('IHDR', ihdrData);
  const plte = pngChunk('PLTE', plteData);
  const trns = pngChunk('tRNS', trnsData);
  const idat = pngChunk('IDAT', compressed);
  const iend = pngChunk('IEND', new Uint8Array(0));

  const parts = [sig, ihdr, plte, trns, idat, iend];
  const total = parts.reduce((a, b) => a + b.length, 0);
  const result = new Uint8Array(total);
  let off = 0;
  for (const p of parts) { result.set(p, off); off += p.length; }

  return new Blob([result], { type: 'image/png' });
}

// パレット量子化とプレビュー表示（市松模様専用）
function generateAndDisplayPalette(imageData) {
  if (!imageData) return;
  const { data: rgbaData } = imageData;
  
  // 255色に量子化（index255は透明色用に予約）
  const quantized = quantizeColors(rgbaData, 255);
  
  // パレット配列: [0..254]=量子化色, [255]=(0,0,0)黒=透明色
  const paletteColors = buildPaletteColors(quantized);

  // state に保存＆プレビュー表示
  state.paletteQuantized = quantized;
  state.paletteColors = paletteColors;
  displayPalettePreview(paletteColors);
}

// パレットプレビューを描画
function displayPalettePreview(paletteColors) {
  palettePreview.innerHTML = '';
  for (let i = 0; i < 256; i++) {
    const c = paletteColors[i] || [0, 0, 0];
    const btn = document.createElement('button');
    btn.className = 'palette-swatch';
    btn.style.backgroundColor = `rgb(${c[0]},${c[1]},${c[2]})`;
    btn.title = `Index ${i}: RGB(${c[0]}, ${c[1]}, ${c[2]})${i === 255 ? ' [透明]' : ''}`;
    btn.type = 'button'; // フォーム送信を防ぐ
    btn.addEventListener('click', (e) => {
      e.preventDefault();
      e.stopPropagation();
      const msg = `Index ${i}: RGB(${c[0]}, ${c[1]}, ${c[2]})${i === 255 ? ' - 透明色' : ''}`;
      if (paletteDetail) paletteDetail.textContent = msg;
      setStatus(msg);
      console.log('Palette clicked:', msg);
    });
    palettePreview.appendChild(btn);
  }
  paletteSection.classList.remove('palette-hidden');
}

// ===== ペイント合成モード: マスク管理・描画 =====
function initPaintMask(width, height) {
  if (!paintOverlayCanvas) return;
  paintState.maskCanvas = document.createElement('canvas');
  paintState.maskCanvas.width = width;
  paintState.maskCanvas.height = height;
  paintState.maskCtx = paintState.maskCanvas.getContext('2d', { willReadFrequently: true });
  paintState.colorOverlayCanvas = document.createElement('canvas');
  paintState.colorOverlayCanvas.width = width;
  paintState.colorOverlayCanvas.height = height;
  paintState.colorOverlayCtx = paintState.colorOverlayCanvas.getContext('2d', { willReadFrequently: true });
  paintOverlayCanvas.width = width;
  paintOverlayCanvas.height = height;
  paintState.undo = [];
  paintState.redo = [];
  syncOverlayDisplaySize();
  renderPaintOverlay();
  updatePaintUndoRedoButtons();
}

function syncOverlayDisplaySize() {
  if (!paintOverlayCanvas || !sourceCanvas) return;
  const rect = sourceCanvas.getBoundingClientRect();
  if (rect.width > 0 && rect.height > 0) {
    paintOverlayCanvas.style.width = rect.width + 'px';
    paintOverlayCanvas.style.height = rect.height + 'px';
  }
}

function renderPaintOverlay() {
  if (!paintOverlayCtx || !paintState.maskCanvas) return;
  const w = paintOverlayCanvas.width;
  const h = paintOverlayCanvas.height;
  paintOverlayCtx.clearRect(0, 0, w, h);
  paintOverlayCtx.drawImage(paintState.maskCanvas, 0, 0);
  paintOverlayCtx.globalCompositeOperation = 'source-in';
  paintOverlayCtx.fillStyle = 'rgba(255, 80, 80, 0.45)';
  paintOverlayCtx.fillRect(0, 0, w, h);
  paintOverlayCtx.globalCompositeOperation = 'source-over';
  if (paintState.colorOverlayCanvas) {
    paintOverlayCtx.globalAlpha = 0.85;
    paintOverlayCtx.drawImage(paintState.colorOverlayCanvas, 0, 0);
    paintOverlayCtx.globalAlpha = 1.0;
  }
  drawLassoPreview();
}

function drawLassoPreview() {
  if (paintState.lassoPoints.length < 2) return;
  const rect = paintOverlayCanvas.getBoundingClientRect();
  const scale = rect.width > 0 ? paintOverlayCanvas.width / rect.width : 1;
  paintOverlayCtx.save();
  paintOverlayCtx.strokeStyle = paintState.tool === 'lassoErase' ? 'rgba(40, 100, 220, 0.95)' : 'rgba(220, 40, 40, 0.95)';
  paintOverlayCtx.lineWidth = Math.max(1, scale * 2);
  paintOverlayCtx.setLineDash([scale * 8, scale * 5]);
  paintOverlayCtx.lineCap = 'round';
  paintOverlayCtx.lineJoin = 'round';
  paintOverlayCtx.beginPath();
  paintOverlayCtx.moveTo(paintState.lassoPoints[0].x, paintState.lassoPoints[0].y);
  for (let i = 1; i < paintState.lassoPoints.length; i += 1) {
    paintOverlayCtx.lineTo(paintState.lassoPoints[i].x, paintState.lassoPoints[i].y);
  }
  paintOverlayCtx.stroke();
  paintOverlayCtx.restore();
}

function finalizeLasso(erase) {
  if (!paintState.maskCtx || paintState.lassoPoints.length < 3) return;
  const drawPath = (ctx) => {
    ctx.beginPath();
    ctx.moveTo(paintState.lassoPoints[0].x, paintState.lassoPoints[0].y);
    for (let i = 1; i < paintState.lassoPoints.length; i += 1) {
      ctx.lineTo(paintState.lassoPoints[i].x, paintState.lassoPoints[i].y);
    }
    ctx.closePath();
  };
  paintState.maskCtx.save();
  paintState.maskCtx.globalCompositeOperation = erase ? 'destination-out' : 'source-over';
  paintState.maskCtx.fillStyle = 'rgba(255,255,255,1)';
  drawPath(paintState.maskCtx);
  paintState.maskCtx.fill();
  paintState.maskCtx.restore();
  // 投げ縄塗・投げ縄消の領域は色オーバーレイも必ず剥がす
  if (paintState.colorOverlayCtx) {
    paintState.colorOverlayCtx.save();
    paintState.colorOverlayCtx.globalCompositeOperation = 'destination-out';
    paintState.colorOverlayCtx.fillStyle = 'rgba(255,255,255,1)';
    drawPath(paintState.colorOverlayCtx);
    paintState.colorOverlayCtx.fill();
    paintState.colorOverlayCtx.restore();
  }
}

function scheduleOverlayRender() {
  if (paintState.rafPending) return;
  paintState.rafPending = true;
  requestAnimationFrame(() => {
    paintState.rafPending = false;
    renderPaintOverlay();
  });
}

function updatePaintUndoRedoButtons() {
  if (paintUndoBtn) paintUndoBtn.disabled = paintState.undo.length === 0;
  if (paintRedoBtn) paintRedoBtn.disabled = paintState.redo.length === 0;
}

function capturePaintSnapshot() {
  const w = paintState.maskCanvas.width;
  const h = paintState.maskCanvas.height;
  return {
    mask: paintState.maskCtx.getImageData(0, 0, w, h),
    color: paintState.colorOverlayCtx ? paintState.colorOverlayCtx.getImageData(0, 0, w, h) : null
  };
}

function restorePaintSnapshot(snap) {
  if (!snap || !snap.mask) return;
  paintState.maskCtx.putImageData(snap.mask, 0, 0);
  if (snap.color && paintState.colorOverlayCtx) paintState.colorOverlayCtx.putImageData(snap.color, 0, 0);
}

function pushPaintUndoSnapshot() {
  if (!paintState.maskCtx || !paintState.maskCanvas) return;
  paintState.undo.push(capturePaintSnapshot());
  if (paintState.undo.length > paintState.undoLimit) paintState.undo.shift();
  paintState.redo.length = 0;
  updatePaintUndoRedoButtons();
}

function paintUndo() {
  if (paintState.undo.length === 0 || !paintState.maskCtx) return;
  paintState.redo.push(capturePaintSnapshot());
  restorePaintSnapshot(paintState.undo.pop());
  renderPaintOverlay();
  updatePaintUndoRedoButtons();
}

function paintRedo() {
  if (paintState.redo.length === 0 || !paintState.maskCtx) return;
  paintState.undo.push(capturePaintSnapshot());
  restorePaintSnapshot(paintState.redo.pop());
  renderPaintOverlay();
  updatePaintUndoRedoButtons();
}

function paintClear() {
  if (!paintState.maskCtx) return;
  pushPaintUndoSnapshot();
  const w = paintState.maskCanvas.width;
  const h = paintState.maskCanvas.height;
  paintState.maskCtx.clearRect(0, 0, w, h);
  if (paintState.colorOverlayCtx) paintState.colorOverlayCtx.clearRect(0, 0, w, h);
  renderPaintOverlay();
}

function paintInvert() {
  if (!paintState.maskCtx) return;
  pushPaintUndoSnapshot();
  const w = paintState.maskCanvas.width;
  const h = paintState.maskCanvas.height;
  const img = paintState.maskCtx.getImageData(0, 0, w, h);
  const d = img.data;
  for (let i = 0; i < d.length; i += 4) {
    d[i] = 255;
    d[i + 1] = 255;
    d[i + 2] = 255;
    d[i + 3] = 255 - d[i + 3];
  }
  paintState.maskCtx.putImageData(img, 0, 0);
  renderPaintOverlay();
}

function eventToImageXY(ev) {
  const r = paintOverlayCanvas.getBoundingClientRect();
  const sx = paintOverlayCanvas.width / r.width;
  const sy = paintOverlayCanvas.height / r.height;
  return {
    x: (ev.clientX - r.left) * sx,
    y: (ev.clientY - r.top) * sy
  };
}

function applyStrokeSegment(x0, y0, x1, y1) {
  if (!paintState.maskCtx) return;
  const erase = paintState.tool === 'eraser';
  paintState.maskCtx.save();
  paintState.maskCtx.globalCompositeOperation = erase ? 'destination-out' : 'source-over';
  paintState.maskCtx.strokeStyle = 'rgba(255,255,255,1)';
  paintState.maskCtx.fillStyle = 'rgba(255,255,255,1)';
  paintState.maskCtx.lineWidth = paintState.size;
  paintState.maskCtx.lineCap = 'round';
  paintState.maskCtx.lineJoin = 'round';
  paintState.maskCtx.beginPath();
  paintState.maskCtx.moveTo(x0, y0);
  paintState.maskCtx.lineTo(x1, y1);
  paintState.maskCtx.stroke();
  paintState.maskCtx.beginPath();
  paintState.maskCtx.arc(x1, y1, paintState.size / 2, 0, Math.PI * 2);
  paintState.maskCtx.fill();
  paintState.maskCtx.restore();
  // ブラシ・消しゴムが通った場所では、過去に置かれたテキスト色を必ず剥がす（原画色に戻す）
  if (paintState.colorOverlayCtx) {
    paintState.colorOverlayCtx.save();
    paintState.colorOverlayCtx.globalCompositeOperation = 'destination-out';
    paintState.colorOverlayCtx.strokeStyle = 'rgba(255,255,255,1)';
    paintState.colorOverlayCtx.fillStyle = 'rgba(255,255,255,1)';
    paintState.colorOverlayCtx.lineWidth = paintState.size;
    paintState.colorOverlayCtx.lineCap = 'round';
    paintState.colorOverlayCtx.lineJoin = 'round';
    paintState.colorOverlayCtx.beginPath();
    paintState.colorOverlayCtx.moveTo(x0, y0);
    paintState.colorOverlayCtx.lineTo(x1, y1);
    paintState.colorOverlayCtx.stroke();
    paintState.colorOverlayCtx.beginPath();
    paintState.colorOverlayCtx.arc(x1, y1, paintState.size / 2, 0, Math.PI * 2);
    paintState.colorOverlayCtx.fill();
    paintState.colorOverlayCtx.restore();
  }
}

function isLassoTool(tool) {
  return tool === 'lassoFill' || tool === 'lassoErase';
}

function composeFontString() {
  const weight = paintState.textBold ? '700' : '500';
  return `${weight} ${paintState.textSize}px ${paintState.textFont}`;
}

function placeTextOnMask(x, y) {
  const text = paintState.textContent;
  if (!paintState.maskCtx || !text) return;
  pushPaintUndoSnapshot();
  const font = composeFontString();
  paintState.maskCtx.save();
  paintState.maskCtx.globalCompositeOperation = 'source-over';
  paintState.maskCtx.fillStyle = 'rgba(255,255,255,1)';
  paintState.maskCtx.textAlign = 'center';
  paintState.maskCtx.textBaseline = 'middle';
  paintState.maskCtx.font = font;
  paintState.maskCtx.fillText(text, x, y);
  paintState.maskCtx.restore();
  if (paintState.colorOverlayCtx) {
    // 先に同じ字形で色を消してから上書き。前回の文字色を完全に置き換えるため。
    paintState.colorOverlayCtx.save();
    paintState.colorOverlayCtx.globalCompositeOperation = 'destination-out';
    paintState.colorOverlayCtx.fillStyle = 'rgba(255,255,255,1)';
    paintState.colorOverlayCtx.textAlign = 'center';
    paintState.colorOverlayCtx.textBaseline = 'middle';
    paintState.colorOverlayCtx.font = font;
    paintState.colorOverlayCtx.fillText(text, x, y);
    paintState.colorOverlayCtx.globalCompositeOperation = 'source-over';
    paintState.colorOverlayCtx.fillStyle = paintState.textColor;
    paintState.colorOverlayCtx.fillText(text, x, y);
    paintState.colorOverlayCtx.restore();
  }
}

function handlePaintPointerDown(ev) {
  if (state.processingMode !== 'paint' || !paintState.maskCtx) return;
  ev.preventDefault();
  paintOverlayCanvas.setPointerCapture(ev.pointerId);
  const { x, y } = eventToImageXY(ev);
  paintState.lastX = x;
  paintState.lastY = y;
  if (paintState.tool === 'text') {
    paintState.drawing = false;
    placeTextOnMask(x, y);
    renderPaintOverlay();
    return;
  }
  paintState.drawing = true;
  if (isLassoTool(paintState.tool)) {
    paintState.lassoPoints = [{ x, y }];
    scheduleOverlayRender();
  } else {
    pushPaintUndoSnapshot();
    applyStrokeSegment(x, y, x, y);
    scheduleOverlayRender();
  }
}

function handlePaintPointerMove(ev) {
  if (!paintState.drawing) return;
  ev.preventDefault();
  const { x, y } = eventToImageXY(ev);
  if (isLassoTool(paintState.tool)) {
    const last = paintState.lassoPoints[paintState.lassoPoints.length - 1];
    const dx = x - last.x;
    const dy = y - last.y;
    if (dx * dx + dy * dy > 4) {
      paintState.lassoPoints.push({ x, y });
      scheduleOverlayRender();
    }
  } else {
    applyStrokeSegment(paintState.lastX, paintState.lastY, x, y);
    paintState.lastX = x;
    paintState.lastY = y;
    scheduleOverlayRender();
  }
}

function handlePaintPointerUp(ev) {
  if (!paintState.drawing) return;
  paintState.drawing = false;
  try { paintOverlayCanvas.releasePointerCapture(ev.pointerId); } catch (_) { /* noop */ }
  if (isLassoTool(paintState.tool)) {
    if (paintState.lassoPoints.length >= 3) {
      pushPaintUndoSnapshot();
      finalizeLasso(paintState.tool === 'lassoErase');
    }
    paintState.lassoPoints = [];
  }
  renderPaintOverlay();
}

function getPaintMaskAlpha(width, height) {
  if (!paintState.maskCtx) return null;
  const img = paintState.maskCtx.getImageData(0, 0, width, height);
  const out = new Uint8Array(width * height);
  for (let i = 0, j = 3; i < out.length; i += 1, j += 4) out[i] = img.data[j];
  return out;
}

// 色オーバーレイで使われている一意の RGB を最大 N 色まで抽出する
function extractColorOverlaySamples() {
  if (!paintState.colorOverlayCtx || !paintState.colorOverlayCanvas) return [];
  const w = paintState.colorOverlayCanvas.width;
  const h = paintState.colorOverlayCanvas.height;
  const data = paintState.colorOverlayCtx.getImageData(0, 0, w, h).data;
  const seen = new Set();
  const out = [];
  for (let i = 0; i < data.length; i += 4) {
    if (data[i + 3] < 128) continue;
    const key = (data[i] << 16) | (data[i + 1] << 8) | data[i + 2];
    if (seen.has(key)) continue;
    seen.add(key);
    out.push([data[i], data[i + 1], data[i + 2]]);
    if (out.length >= 32) break;
  }
  return out;
}

// テキスト色をパレット量子化で必ず拾わせるための密サンプル ImageData を作る
function buildTextColorSampleImage(colors) {
  if (!colors.length) return null;
  const perColor = 1024;
  const total = colors.length * perColor;
  const img = new ImageData(total, 1);
  let p = 0;
  for (const [r, g, b] of colors) {
    for (let k = 0; k < perColor; k += 1) {
      const o = p * 4;
      img.data[o] = r;
      img.data[o + 1] = g;
      img.data[o + 2] = b;
      img.data[o + 3] = 255;
      p += 1;
    }
  }
  return img;
}

// ===== ペイント合成 Tap me 処理 =====
async function processPaintComposite(sourceImageData) {
  if (!sourceImageData) throw new Error('画像を読み込んでください。');
  const width = sourceImageData.width;
  const height = sourceImageData.height;
  const maskAlpha = getPaintMaskAlpha(width, height);
  if (!maskAlpha) throw new Error('マスクが初期化されていません。');

  const bSource = applyGammaToImageData(sourceImageData);
  state.histogramOriginal = computeHistogram(sourceImageData);
  state.histogramGamma = state.gammaEnabled && state.gammaValue !== 0 ? computeHistogram(bSource) : null;

  setStatus('共通パレット作成中...');
  const textColors = extractColorOverlaySamples();
  const paletteInputs = [bSource];
  const textSampleImg = buildTextColorSampleImage(textColors);
  if (textSampleImg) paletteInputs.push(textSampleImg);
  const quantized = quantizeColorsFromImageDataList(paletteInputs, 255);
  const paletteColors = buildPaletteColors(quantized);
  const findNearest = buildNearestFinder(quantized);
  const sharedIndices = mapImageDataToPaletteIndices(bSource, findNearest);

  // テキスト色 → パレットインデックスの事前計算
  const colorOverlayData = paintState.colorOverlayCtx
    ? paintState.colorOverlayCtx.getImageData(0, 0, width, height).data
    : null;

  const finalIndices = new Uint8Array(width * height);
  const timerRef = { last: performance.now() };

  for (let y = 0; y < height; y += 1) {
    for (let x = 0; x < width; x += 1) {
      const i = y * width + x;
      // 塗っていない部分 = A 完全透明 → B'（市松適用後の source）が見える
      const bPrimeIndex = isCheckerboardVisiblePixel(x, y) ? sharedIndices[i] : 255;
      if (maskAlpha[i] > 0) {
        if (colorOverlayData && colorOverlayData[i * 4 + 3] >= 128) {
          finalIndices[i] = findNearest(
            colorOverlayData[i * 4],
            colorOverlayData[i * 4 + 1],
            colorOverlayData[i * 4 + 2]
          );
        } else {
          finalIndices[i] = sharedIndices[i];
        }
      } else {
        finalIndices[i] = bPrimeIndex;
      }
    }
    await maybeYield('ペイント合成中...', y + 1, height, timerRef);
  }

  const outputImageData = imageDataFromPaletteIndices(width, height, finalIndices, paletteColors);
  state.histogramOutput = computeHistogram(outputImageData);
  state.paletteQuantized = quantized;
  state.paletteColors = paletteColors;
  state.outputIndices = finalIndices;
  state.outputPaletteColors = paletteColors;

  return {
    imageData: outputImageData,
    summary: {
      fileName: state.file?.name ?? 'paint',
      mode: 'paint',
      modeLabel: 'Paint composite',
      width,
      height
    }
  };
}

async function downloadPaintCompositeOutput() {
  if (!state.outputIndices || !state.outputPaletteColors || !state.summary) return;
  downloadButton.disabled = true;
  setStatus('ペイント合成パレットPNG生成中...');
  try {
    const blob = encodePalettePNG(state.summary.width, state.summary.height, state.outputIndices, state.outputPaletteColors);
    const baseName = state.file?.name?.replace(/\.[^.]+$/, '') || 'paint';
    downloadBlob(blob, `${baseName}_paint_composite.png`);
    setStatus('Processing complete. Check Before / After.');
  } catch (err) {
    console.error(err);
    setStatus(`保存失敗: ${err.message}`);
  } finally {
    downloadButton.disabled = false;
  }
}

// ===== A/B 合成 Tap me 処理 =====
async function processCompositeTapMe(imageDataA, imageDataB) {
  if (!imageDataA || !imageDataB) throw new Error('A画像とB画像を両方読み込んでください。');
  if (imageDataA.width !== imageDataB.width || imageDataA.height !== imageDataB.height) {
    throw new Error(`A画像とB画像のサイズを一致させてください。A=${imageDataA.width}×${imageDataA.height}, B=${imageDataB.width}×${imageDataB.height}`);
  }

  const width = imageDataA.width;
  const height = imageDataA.height;
  const aSource = applyGammaToImageData(imageDataA);
  const bSource = applyGammaToImageData(imageDataB);

  state.histogramOriginal = computeHistogram(aSource);
  state.histogramGamma = state.gammaEnabled && state.gammaValue !== 0 ? computeHistogram(bSource) : null;

  setStatus('共通パレット作成中...');
  const quantized = quantizeColorsFromImageDataList([aSource, bSource], 255);
  const paletteColors = buildPaletteColors(quantized);
  const findNearest = buildNearestFinder(quantized);
  const aIndices = mapImageDataToPaletteIndices(aSource, findNearest);
  const bIndices = mapImageDataToPaletteIndices(bSource, findNearest);

  const finalIndices = new Uint8Array(width * height);
  const timerRef = { last: performance.now() };

  for (let y = 0; y < height; y += 1) {
    for (let x = 0; x < width; x += 1) {
      const i = y * width + x;
      const o = i * 4;

      // B' は既存の「市松模様」処理と同じ配置で作る。
      // 保持位置は B のパレットインデックス、非保持位置は index 255 の透明。
      const bPrimeIndex = isCheckerboardVisiblePixel(x, y) ? bIndices[i] : 255;

      // 合成規則は案1で固定する。
      // A が少しでも不透明なら A の色を採用し、A が完全透明なら下の B' を通す。
      // ここでは半透明の alpha ブレンドは行わない。
      const aAlpha = aSource.data[o + 3];
      finalIndices[i] = aAlpha > 0 ? aIndices[i] : bPrimeIndex;
    }
    await maybeYield('A/B 合成中...', y + 1, height, timerRef);
  }

  const outputImageData = imageDataFromPaletteIndices(width, height, finalIndices, paletteColors);
  state.histogramOutput = computeHistogram(outputImageData);
  state.paletteQuantized = quantized;
  state.paletteColors = paletteColors;
  state.outputIndices = finalIndices;
  state.outputPaletteColors = paletteColors;

  return {
    imageData: outputImageData,
    summary: {
      fileName: `${state.fileA?.name ?? 'A'} + ${state.fileB?.name ?? 'B'}`,
      mode: 'composite',
      modeLabel: 'A/B composite',
      width,
      height
    }
  };
}

async function downloadCompositeOutput() {
  if (!state.outputIndices || !state.outputPaletteColors || !state.summary) return;
  downloadButton.disabled = true;
  setStatus('A/B 合成パレットPNG生成中...');
  try {
    const blob = encodePalettePNG(state.summary.width, state.summary.height, state.outputIndices, state.outputPaletteColors);
    const baseNameA = state.fileA?.name?.replace(/\.[^.]+$/, '') || 'A';
    const baseNameB = state.fileB?.name?.replace(/\.[^.]+$/, '') || 'B';
    downloadBlob(blob, `${baseNameA}_${baseNameB}_tapme_composite.png`);
    setStatus('Processing complete. Check Before / After.');
  } catch (err) {
    console.error(err);
    setStatus(`保存失敗: ${err.message}`);
  } finally {
    downloadButton.disabled = false;
  }
}

// 市松模様モード専用ダウンロード（パレットPNG出力）
async function downloadCheckerboardOutput() {
  if (!state.outputImageData) return;
  const { width, height, data: rgbaData } = state.outputImageData;

  downloadButton.disabled = true;
  setStatus('パレットPNG生成中...');

  try {
    // パレット量子化が済んでいなければ実行
    if (!state.paletteQuantized) {
      generateAndDisplayPalette(state.outputImageData);
    }
    
    const findNearest = buildNearestFinder(state.paletteQuantized);
    const paletteColors = state.paletteColors;

    // 各ピクセルをパレットインデックスにマッピング
    const indices = new Uint8Array(width * height);
    for (let i = 0; i < width * height; i++) {
      const o = i * 4;
      indices[i] = rgbaData[o + 3] === 0
        ? 255
        : findNearest(rgbaData[o], rgbaData[o+1], rgbaData[o+2]);
    }

    const blob = encodePalettePNG(width, height, indices, paletteColors);
    const baseName = state.file?.name?.replace(/\.[^.]+$/, '') || 'output';
    downloadBlob(blob, `${baseName}_checkerboard.png`);
    setStatus('Processing complete. Check Before / After.');
  } catch (err) {
    console.error(err);
    setStatus(`保存失敗: ${err.message}`);
  } finally {
    downloadButton.disabled = false;
  }
}

// ===== 入出力 =====
async function readFileAsImageData(file) {
  const url = URL.createObjectURL(file);
  try {
    const image = await new Promise((resolve, reject) => {
      const img = new Image();
      img.onload = () => resolve(img);
      img.onerror = reject;
      img.src = url;
    });
    const canvas = document.createElement('canvas');
    canvas.width = image.naturalWidth;
    canvas.height = image.naturalHeight;
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    ctx.drawImage(image, 0, 0);
    return {
      imageData: ctx.getImageData(0, 0, canvas.width, canvas.height),
      width: canvas.width,
      height: canvas.height
    };
  } finally {
    URL.revokeObjectURL(url);
  }
}

async function loadFile(file) {
  const url = URL.createObjectURL(file);
  try {
    const image = await new Promise((resolve, reject) => {
      const img = new Image();
      img.onload = () => resolve(img);
      img.onerror = reject;
      img.src = url;
    });

    sourceCanvas.width = image.naturalWidth;
    sourceCanvas.height = image.naturalHeight;
    sourceCtx.clearRect(0, 0, sourceCanvas.width, sourceCanvas.height);
    sourceCtx.drawImage(image, 0, 0);

    state.file = file;
    state.sourceImageData = sourceCtx.getImageData(0, 0, sourceCanvas.width, sourceCanvas.height);
    resetOutputState();

    if (state.processingMode === 'paint') {
      initPaintMask(image.naturalWidth, image.naturalHeight);
    } else {
      paintState.maskCanvas = null;
      paintState.maskCtx = null;
      paintState.undo = [];
      paintState.redo = [];
    }

    fileMeta.innerHTML = `File: <strong>${file.name}</strong><br>Size: <strong>${image.naturalWidth} × ${image.naturalHeight}</strong><br>Type: <strong>${file.type || "unknown"}</strong>`;
    beforeMeta.textContent = `${image.naturalWidth} × ${image.naturalHeight}`;

    processButton.disabled = false;
    setStatus("Image loaded. Ready to process.");
  } finally {
    URL.revokeObjectURL(url);
  }
}

async function loadCompositeFile(kind, file) {
  const result = await readFileAsImageData(file);
  if (kind === 'A') {
    state.fileA = file;
    state.imageDataA = result.imageData;
    if (fileMetaA) fileMetaA.innerHTML = `A: <strong>${file.name}</strong><br>${result.width} × ${result.height} / ${file.type || 'unknown'}`;
    sourceCanvas.width = result.width;
    sourceCanvas.height = result.height;
    sourceCtx.putImageData(result.imageData, 0, 0);
    beforeMeta.textContent = `A: ${result.width} × ${result.height}`;
  } else {
    state.fileB = file;
    state.imageDataB = result.imageData;
    if (fileMetaB) fileMetaB.innerHTML = `B: <strong>${file.name}</strong><br>${result.width} × ${result.height} / ${file.type || 'unknown'}`;
    if (!state.imageDataA) {
      sourceCanvas.width = result.width;
      sourceCanvas.height = result.height;
      sourceCtx.putImageData(result.imageData, 0, 0);
      beforeMeta.textContent = `B: ${result.width} × ${result.height}`;
    }
  }

  resetOutputState();
  const aLoaded = !!state.imageDataA;
  const bLoaded = !!state.imageDataB;
  processButton.disabled = !(aLoaded && bLoaded);
  fileMeta.innerHTML = `A画像: <strong>${state.fileA?.name ?? '未選択'}</strong><br>B画像: <strong>${state.fileB?.name ?? '未選択'}</strong>`;
  setStatus(aLoaded && bLoaded ? 'A/B 画像を読み込みました。処理できます。' : 'A画像とB画像を両方読み込んでください。');
}

async function runProcessing() {
  if (state.processingMode === 'composite') {
    if (!state.imageDataA || !state.imageDataB) {
      setStatus("A画像とB画像を両方読み込んでください。");
      return;
    }
  } else if (state.processingMode === 'paint') {
    if (!state.sourceImageData) {
      setStatus("画像を読み込んでください。");
      return;
    }
    if (!paintState.maskCtx) {
      setStatus("マスクが初期化されていません。");
      return;
    }
  } else if (!state.sourceImageData) {
    setStatus("Please load an image first.");
    return;
  }

  processButton.disabled = true;
  downloadButton.disabled = true;

  try {
    const result = state.processingMode === 'checkerboard'
      ? await processCheckerboard(state.sourceImageData)
      : state.processingMode === 'composite'
        ? await processCompositeTapMe(state.imageDataA, state.imageDataB)
        : state.processingMode === 'paint'
          ? await processPaintComposite(state.sourceImageData)
          : await processHighFreqCut(state.sourceImageData);

    outputCanvas.width = result.imageData.width;
    outputCanvas.height = result.imageData.height;
    outputCtx.putImageData(result.imageData, 0, 0);
    state.outputImageData = result.imageData;
    state.summary = result.summary;
    updateSummaryDisplay(result.summary);
    downloadButton.disabled = false;
    
    // ヒストグラムを描画
    drawHistogram(histogramOriginalCanvas, histogramOriginalCtx, state.histogramOriginal);
    drawHistogram(histogramOutputCanvas, histogramOutputCtx, state.histogramOutput);
    
    // ガンマ補正が有効な場合のみガンマ補正後のハートグラムを表示
    if (state.gammaEnabled && state.histogramGamma) {
      histogramGammaContainer.classList.remove("histogram-hidden");
      drawHistogram(histogramGammaCanvas, histogramGammaCtx, state.histogramGamma);
    } else {
      histogramGammaContainer.classList.add("histogram-hidden");
    }
    
    // 市松模様・A/B合成・ペイント合成モード時はパレットを表示
    if (state.processingMode === 'checkerboard') {
      generateAndDisplayPalette(result.imageData);
    } else if (state.processingMode === 'composite' || state.processingMode === 'paint') {
      displayPalettePreview(state.outputPaletteColors);
    } else {
      // 通常モード時はパレットを非表示
      paletteSection.classList.add('palette-hidden');
    }
    
    setStatus("Processing complete. Check Before / After.");
  } catch (error) {
    console.error(error);
    setStatus(`Processing failed: ${error.message}`);
  } finally {
    processButton.disabled = false;
  }
}

async function downloadOutput() {
  if (!state.outputImageData) return;
  if (state.processingMode === 'checkerboard') {
    await downloadCheckerboardOutput();
    return;
  }
  if (state.processingMode === 'composite') {
    await downloadCompositeOutput();
    return;
  }
  if (state.processingMode === 'paint') {
    await downloadPaintCompositeOutput();
    return;
  }
  const blob = await new Promise((resolve) => outputCanvas.toBlob(resolve, "image/png"));
  if (!blob) {
    setStatus("Failed to create save data.");
    return;
  }
  const baseName = state.file?.name?.replace(/\.[^.]+$/, "") || "output";
  downloadBlob(blob, `${baseName}_processed.png`);
}

function handleFiles(fileList) {
  const file = fileList?.[0];
  if (!file) return;

  if (state.processingMode === 'composite') {
    const fileB = fileList?.[1];
    const tasks = [loadCompositeFile('A', file)];
    if (fileB) tasks.push(loadCompositeFile('B', fileB));
    Promise.all(tasks).catch((error) => {
      console.error(error);
      setStatus(`Image loading failed: ${error.message}`);
    });
    return;
  }

  loadFile(file).catch((error) => {
    console.error(error);
    setStatus(`Image loading failed: ${error.message}`);
  });
}

dropzone.addEventListener("click", () => fileInput.click());
dropzone.addEventListener("keydown", (event) => {
  if (event.key === "Enter" || event.key === " ") {
    event.preventDefault();
    fileInput.click();
  }
});

["dragenter", "dragover"].forEach((eventName) => {
  dropzone.addEventListener(eventName, (event) => {
    event.preventDefault();
    dropzone.classList.add("dragover");
  });
});

["dragleave", "drop"].forEach((eventName) => {
  dropzone.addEventListener(eventName, (event) => {
    event.preventDefault();
    if (eventName === "drop") {
      handleFiles(event.dataTransfer.files);
    }
    dropzone.classList.remove("dragover");
  });
});

function bindCompositeDrop(dropElement, kind) {
  if (!dropElement) return;
  ["dragenter", "dragover"].forEach((eventName) => {
    dropElement.addEventListener(eventName, (event) => {
      event.preventDefault();
      dropElement.classList.add("dragover");
    });
  });
  ["dragleave", "drop"].forEach((eventName) => {
    dropElement.addEventListener(eventName, (event) => {
      event.preventDefault();
      if (eventName === "drop") {
        const file = event.dataTransfer.files?.[0];
        if (file) loadCompositeFile(kind, file).catch((error) => {
          console.error(error);
          setStatus(`${kind}画像の読み込み失敗: ${error.message}`);
        });
      }
      dropElement.classList.remove("dragover");
    });
  });
}

bindCompositeDrop(compositeDropA, 'A');
bindCompositeDrop(compositeDropB, 'B');

fileInput.addEventListener("change", (event) => handleFiles(event.target.files));
if (fileInputA) fileInputA.addEventListener("change", (event) => {
  const file = event.target.files?.[0];
  if (file) loadCompositeFile('A', file).catch((error) => {
    console.error(error);
    setStatus(`A画像の読み込み失敗: ${error.message}`);
  });
});
if (fileInputB) fileInputB.addEventListener("change", (event) => {
  const file = event.target.files?.[0];
  if (file) loadCompositeFile('B', file).catch((error) => {
    console.error(error);
    setStatus(`B画像の読み込み失敗: ${error.message}`);
  });
});
if (compositeDropA) compositeDropA.addEventListener("click", () => fileInputA?.click());
if (compositeDropB) compositeDropB.addEventListener("click", () => fileInputB?.click());
processButton.addEventListener("click", runProcessing);
downloadButton.addEventListener("click", downloadOutput);

// ===== タイル色選択 =====
tileColorInput.addEventListener("change", (event) => {
  const hex = event.target.value; // #RRGGBB format
  state.tileColor = {
    r: parseInt(hex.slice(1, 3), 16),
    g: parseInt(hex.slice(3, 5), 16),
    b: parseInt(hex.slice(5, 7), 16)
  };
});

// ===== ガンマ補正 =====
gammaToggle.addEventListener("change", (event) => {
  state.gammaEnabled = event.target.checked;
  gammaControls.style.display = state.gammaEnabled ? 'grid' : 'none';
  
  // ガンマ補正が無効になった場合、ハートグラムを隠す
  if (!state.gammaEnabled) {
    histogramGammaContainer.classList.add("histogram-hidden");
  }
});

gammaSlider.addEventListener("input", (event) => {
  const value = parseFloat(event.target.value);
  state.gammaValue = value;
  gammaValue.textContent = value.toFixed(1);
});

// ===== 処理モード切り替えタブ =====
function switchProcessingMode(mode) {
  state.processingMode = mode;
  paletteSection.classList.add('palette-hidden');

  const setTab = (tab, active) => {
    if (!tab) return;
    tab.classList.toggle("active", active);
    tab.setAttribute("aria-selected", active ? "true" : "false");
  };

  setTab(modeTabNormal, mode === 'normal');
  setTab(modeTabCheckerboard, mode === 'checkerboard');
  setTab(modeTabComposite, mode === 'composite');
  setTab(modeTabPaint, mode === 'paint');

  normalControls.style.display = mode === 'normal' ? "grid" : "none";
  if (compositeControls) compositeControls.style.display = mode === 'composite' ? "grid" : "none";
  if (paintControls) paintControls.style.display = mode === 'paint' ? "grid" : "none";
  if (singleInputGroup) singleInputGroup.style.display = mode === 'composite' ? "none" : "grid";
  if (compositeInputGroup) compositeInputGroup.style.display = mode === 'composite' ? "grid" : "none";

  if (paintOverlayCanvas) {
    paintOverlayCanvas.style.display = mode === 'paint' ? 'block' : 'none';
    paintOverlayCanvas.classList.toggle('active', mode === 'paint');
  }

  if (mode === 'composite') {
    processButton.disabled = !(state.imageDataA && state.imageDataB);
    fileMeta.innerHTML = `A画像: <strong>${state.fileA?.name ?? '未選択'}</strong><br>B画像: <strong>${state.fileB?.name ?? '未選択'}</strong>`;
    setStatus(state.imageDataA && state.imageDataB ? 'A/B 画像を処理できます。' : 'A画像とB画像を両方読み込んでください。');
  } else if (mode === 'paint') {
    if (state.sourceImageData) {
      const w = state.sourceImageData.width;
      const h = state.sourceImageData.height;
      if (!paintState.maskCanvas || paintState.maskCanvas.width !== w || paintState.maskCanvas.height !== h) {
        initPaintMask(w, h);
      } else {
        syncOverlayDisplaySize();
        renderPaintOverlay();
      }
      processButton.disabled = false;
      setStatus('塗り終わったら処理してください。');
    } else {
      processButton.disabled = true;
      setStatus('画像を読み込むとペイントできます。');
    }
  } else {
    processButton.disabled = !state.sourceImageData;
    setStatus(state.sourceImageData ? 'Image loaded. Ready to process.' : '画像を読み込むと処理できます。');
  }
}

modeTabNormal.addEventListener("click", () => switchProcessingMode("normal"));
modeTabCheckerboard.addEventListener("click", () => switchProcessingMode("checkerboard"));
if (modeTabComposite) modeTabComposite.addEventListener("click", () => switchProcessingMode("composite"));
if (modeTabPaint) modeTabPaint.addEventListener("click", () => switchProcessingMode("paint"));

// ===== ペイント合成: イベントバインド =====
if (paintOverlayCanvas) {
  paintOverlayCanvas.addEventListener('pointerdown', handlePaintPointerDown);
  paintOverlayCanvas.addEventListener('pointermove', handlePaintPointerMove);
  paintOverlayCanvas.addEventListener('pointerup', handlePaintPointerUp);
  paintOverlayCanvas.addEventListener('pointercancel', handlePaintPointerUp);
  paintOverlayCanvas.addEventListener('pointerleave', handlePaintPointerUp);
}

function setPaintTool(tool) {
  paintState.tool = tool;
  if (paintToolBrush) paintToolBrush.classList.toggle('active', tool === 'brush');
  if (paintToolEraser) paintToolEraser.classList.toggle('active', tool === 'eraser');
  if (paintToolLassoFill) paintToolLassoFill.classList.toggle('active', tool === 'lassoFill');
  if (paintToolLassoErase) paintToolLassoErase.classList.toggle('active', tool === 'lassoErase');
  if (paintToolText) paintToolText.classList.toggle('active', tool === 'text');
}

if (paintToolBrush) paintToolBrush.addEventListener('click', () => setPaintTool('brush'));
if (paintToolEraser) paintToolEraser.addEventListener('click', () => setPaintTool('eraser'));
if (paintToolLassoFill) paintToolLassoFill.addEventListener('click', () => setPaintTool('lassoFill'));
if (paintToolLassoErase) paintToolLassoErase.addEventListener('click', () => setPaintTool('lassoErase'));
if (paintToolText) paintToolText.addEventListener('click', () => setPaintTool('text'));

if (paintTextInput) paintTextInput.addEventListener('input', (event) => {
  paintState.textContent = event.target.value;
});
if (paintTextFontSelect) paintTextFontSelect.addEventListener('change', (event) => {
  paintState.textFont = event.target.value;
});
if (paintTextSizeSlider) paintTextSizeSlider.addEventListener('input', (event) => {
  const v = parseInt(event.target.value, 10);
  paintState.textSize = v;
  if (paintTextSizeValueLabel) paintTextSizeValueLabel.textContent = String(v);
});
if (paintTextBoldToggle) paintTextBoldToggle.addEventListener('change', (event) => {
  paintState.textBold = !!event.target.checked;
});
if (paintTextColorInput) paintTextColorInput.addEventListener('input', (event) => {
  paintState.textColor = event.target.value;
});
if (paintSizeSlider) paintSizeSlider.addEventListener('input', (event) => {
  const v = parseInt(event.target.value, 10);
  paintState.size = v;
  if (paintSizeValueLabel) paintSizeValueLabel.textContent = String(v);
});
if (paintUndoBtn) paintUndoBtn.addEventListener('click', paintUndo);
if (paintRedoBtn) paintRedoBtn.addEventListener('click', paintRedo);
if (paintInvertBtn) paintInvertBtn.addEventListener('click', paintInvert);
if (paintClearBtn) paintClearBtn.addEventListener('click', paintClear);

window.addEventListener('resize', () => {
  if (state.processingMode === 'paint') syncOverlayDisplaySize();
});
